package com.pridesys.ticketing.repository;
import com.pridesys.ticketing.dto.UsersProjectsDtos; import com.pridesys.ticketing.entity.ProjectRecord; import java.sql.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class ProjectRepository { private final JdbcTemplate jdbc; public ProjectRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<ProjectRecord> findAll(){return jdbc.query("SELECT id,name,short_code,description,active FROM projects ORDER BY name",this::map);} public long create(UsersProjectsDtos.CreateProjectRequest r){var h=new org.springframework.jdbc.support.GeneratedKeyHolder();jdbc.update(c->{var p=c.prepareStatement("INSERT INTO projects(name,short_code,description) VALUES (?,?,?)",Statement.RETURN_GENERATED_KEYS);p.setString(1,r.name().trim());p.setString(2,r.shortCode().trim().toUpperCase());p.setString(3,r.description());return p;},h);return h.getKey().longValue();}
 public void update(long id,UsersProjectsDtos.UpdateProjectRequest r){jdbc.update("UPDATE projects SET name=?,description=?,active=COALESCE(?,active) WHERE id=?",r.name().trim(),r.description(),r.active(),id);} public boolean member(long project,long user){return jdbc.queryForObject("SELECT COUNT(*) FROM project_memberships WHERE project_id=? AND user_id=?",Integer.class,project,user)>0;}
 public void addMember(long project,long user){jdbc.update("INSERT IGNORE INTO project_memberships(project_id,user_id) VALUES (?,?)",project,user);} public void removeMember(long project,long user){jdbc.update("DELETE FROM project_memberships WHERE project_id=? AND user_id=?",project,user);}
 public List<ProjectRecord> forUser(long user){return jdbc.query("SELECT p.id,p.name,p.short_code,p.description,p.active FROM projects p JOIN project_memberships m ON m.project_id=p.id WHERE m.user_id=? ORDER BY p.name",this::map,user);}
 private ProjectRecord map(ResultSet r,int n)throws SQLException{return new ProjectRecord(r.getLong("id"),r.getString("name"),r.getString("short_code"),r.getString("description"),r.getBoolean("active"));}}
